-- One-time import: HubSpot clinic contacts who are marketing contacts (opted in), onto the Clinics list.
-- Checked against existing contacts by email: nobody is added twice, and contacts already sorted onto a
-- list or set aside keep that decision. A summary is printed to the deploy log.
create temp table hs_clinics (email text, first_name text, last_name text, company text, address text, address2 text, city text, state text, zip text, phone text) on commit drop;

do $$
declare total int; existing int; moved int; added int; leads int;
begin
  select count(distinct lower(email)) into total from hs_clinics;
  select count(*) into existing from contact_imports c where lower(c.email) in (select lower(email) from hs_clinics);
  select count(distinct lower(l.email)) into leads from leads l where lower(l.email) in (select lower(email) from hs_clinics);

  select distinct on (lower(h.email)) lower(h.email), h.first_name, h.last_name, h.company, h.address, h.address2, h.city, h.state, h.zip, h.phone,
    'hubspot', 'HubSpot clinic contacts (2026-11-22)', 'clinics', 'assigned', now()
  from hs_clinics h
  where not exists (select 1 from contact_imports c where lower(c.email) = lower(h.email))
  order by lower(h.email);
  get diagnostics added = row_count;

  update contact_imports c set status = 'assigned', list = 'clinics', assigned_at = now(), updated_at = now()
  where c.status = 'pending' and lower(c.email) in (select lower(email) from hs_clinics);
  get diagnostics moved = row_count;

  raise notice '[clinic import] % in file; % new contacts added to Clinics; % already on file (% moved from Pending to Clinics, % left on their existing list or set aside); % also match website leads',
    total, added, existing, moved, existing - moved, leads;
end $$;
